public CompletableFuture<PaymentResponse> processPayment(PaymentRequest request, Duration deadline) {
    long timeoutMs = deadline.toMillis();
    return CompletableFuture.supplyAsync(() -> executeGatewayCall(request))
        .orTimeout(timeoutMs, TimeUnit.MILLISECONDS)
        .exceptionally(ex -> {
            if (ex instanceof TimeoutException) {
                throw new ServiceStatusException(Status.DEADLINE_EXCEEDED, "Payment timed out after " + timeoutMs + "ms", Map.of("traceId", MDC.get("traceId")));
            }
            throw new ServiceStatusException(Status.UNAVAILABLE, "Payment gateway unreachable", Map.of("cause", ex.getMessage()));
        });
}
